"""Kitchen Sink page: Chart (VB's MSChart): bars, lines, areas, a pie and more from a
table of data (ChartData), a title, a legend and axes; clicking a bar or a point fires
PointSelected. It follows the window's light or dark scheme."""

import random

from vp6 import *

TYPES = ("Line", "Spline", "Area", "Bar", "Stacked bar", "Percent bar", "Horizontal bar",
         "Pie", "Scatter")


class pgChart(Form):
    # region VP6 Designer - generated by the form designer, do not edit
    def InitializeComponent(self):
        self.Caption = 'Charts'
        self.Width = 640
        self.Height = 440
        self.chtSales = Chart(self, Left=16, Top=16, Width=440, Height=360,
                              Title='Sales and costs', AxisYTitle='Thousands of EUR')
        self.lblType = Label(self, Caption='ChartType:', Left=472, Top=16, Width=152, Height=22,
                             TabIndex=1)
        self.cboType = ComboBox(self, Style=2, Left=472, Top=40, Width=152, Height=25, TabIndex=2)
        self.chkLegend = CheckBox(self, Caption='&Legend', Left=472, Top=80, Width=152, Height=25,
                                  Value=1, TabIndex=3)
        self.chkLog = CheckBox(self, Caption='L&ogarithmic', Left=472, Top=108, Width=152,
                               Height=25, TabIndex=4, ToolTipText='LogScale: a logarithmic Y axis')
        self.cmdData = CommandButton(self, Caption='&New data', Left=472, Top=148, Width=152,
                                     Height=32, TabIndex=5,
                                     ToolTipText='ChartData from a list of rows')
        self.cmdCopy = CommandButton(self, Caption='&Copy', Left=472, Top=188, Width=152,
                                     Height=32, TabIndex=6,
                                     ToolTipText='EditCopy: the chart on the clipboard, as a picture')
        self.lblPoint = Label(self, Caption='Click a bar or a point', Left=16, Top=388, Width=608,
                              Height=40, WordWrap=True, TabIndex=7)
    # endregion

    def Form_Load(self):
        for name in TYPES:
            self.cboType.AddItem(name)
        self.cboType.ListIndex = self.chtSales.ChartType

    def cboType_Click(self):
        self.chtSales.ChartType = self.cboType.ListIndex  # (vpChartLine... in this order)

    def chkLegend_Click(self):
        self.chtSales.Legend = vpLegendBottom if self.chkLegend.Value == vpChecked \
            else vpLegendNone

    def chkLog_Click(self):
        self.chtSales.LogScale = self.chkLog.Value == vpChecked

    def cmdData_Click(self):
        rows = [["", "Sales", "Costs", "Profit"]]
        for quarter in ("Q1", "Q2", "Q3", "Q4"):
            sales, costs = random.randint(8, 20), random.randint(4, 12)
            rows.append([quarter, sales, costs, max(sales - costs, 0)])
        self.chtSales.ChartData = rows
        self.lblPoint.Caption = f"New data: {self.chtSales.RowCount} rows, " \
                                f"{self.chtSales.ColumnCount} series"

    def cmdCopy_Click(self):
        self.chtSales.EditCopy()
        self.lblPoint.Caption = "The chart is on the clipboard"

    def chtSales_PointSelected(self, Series, DataPoint):
        chart = self.chtSales
        self.lblPoint.Caption = (f"PointSelected: {chart.ColumnLabel(Series)} in "
                                 f"{chart.RowLabel(DataPoint)} = {chart.Data(DataPoint, Series)}")


if __name__ == "__main__":
    run(pgChart)
